// Gives Gradle more memory than Expo's template (-Xmx2048m, 512m metaspace).
// With Sentry and expo-updates added, release builds died in
// lintVitalAnalyzeRelease with "Metaspace". android/ is regenerated by
// `expo prebuild`, so the setting has to live here to survive that — and to
// apply on EAS builders too.
const { withGradleProperties } = require('expo/config-plugins');

const KEY = 'org.gradle.jvmargs';
const VALUE = '-Xmx4096m -XX:MaxMetaspaceSize=1024m -XX:+HeapDumpOnOutOfMemoryError -Dfile.encoding=UTF-8';

module.exports = function withGradleMemory(config) {
  return withGradleProperties(config, (cfg) => {
    cfg.modResults = cfg.modResults.filter((item) => !(item.type === 'property' && item.key === KEY));
    cfg.modResults.push({ type: 'property', key: KEY, value: VALUE });
    return cfg;
  });
};
